# vj11: single-file ARC-AGI-3 game. Glow-up of vj01, the walker.
# Author: Claude Sonnet 5.5 High (15-Oct-2026); revised by Claude Opus 5.5 High (18-Oct-2026)
# Date: 18-October-2026
# PURPOSE: vj01 is a plain recolour and turn of a public game; this version is a revision of it with
#   the walker: a green free piece that the arrow actions move; shown colours; landing answer; long win animation. The level data and rule code are the game's own; the layer on top is built by
#   polish/vj11/build/build_vj.py from engine.tmpl and game.tmpl, so the four VJ glow-ups share one pass.
# SRP/DRY check: Pass. One game file; the shared pass is generated, not copied by hand.
# CHANGELOG
# - 18-Oct-2026 Claude Opus 5.5 High: the Boss's review (buttons odd and touching the level indicator, the
#   indicator over the board, a new pink thing on level two that seemed to do nothing). The level dots and the
#   budget now share one strip on the top row that no board reaches; buttons are the control copy's solid grey
#   and purple shapes and touch nothing; the walker and its frame are green and the walls maroon (no pink);
#   every press flashes the tracks it turned; walker pockets re-placed clear of the buttons; budgets about
#   twice each line.
# - 15-Oct-2026 Claude Sonnet 5.5 High: new game vj11 (revision of vj01): the walker: a green free piece that the arrow actions move; shown colours; landing answer; long win animation.
#
