# -- glow-up sprites: the colours the player sees --------------------------------------------------------------
# Tiles light blue on a blue board, buttons pink with a white chevron (a thin "<" for L, a solid ">" for R, so the
# two can never be mixed up after a turn), frames drawn as hollow boxes in the colour of the piece they want.
# (vj11, 18-Oct) the control copy's own buttons: one solid colour each, grey for L and purple for R, the rounded side
# showing the way the track turns; the two-colour chevrons read as strange to the Boss
_VJ_L = [[-1, 3, 3], [3, 3, 3], [3, 3, 3], [-1, 3, 3]]
_VJ_R = [[15, 15, -1], [15, 15, 15], [15, 15, 15], [15, 15, -1]]


def _vj_box(c):
    return [[c, c, c, c], [c, -1, -1, c], [c, -1, -1, c], [c, c, c, c]]


def _vj_put(key, pixels, tags):
    sprites[key] = Sprite(pixels=pixels, name=key, visible=True, collidable=True, tags=tags)


for _k, _s in list(sprites.items()):
    _t = _s.tags[0]
    if _t == "tile":
        _vj_put(_k, [[10, 10], [10, 10]], ["tile"])
    elif _t.startswith("button"):
        _vj_put(_k, _VJ_R if _t.endswith("_R") else _VJ_L, list(_s.tags))
    elif _t == "bghvgbtwcb":
        _vj_put(_k, _vj_box(11), [_t])
    elif _t == "fdgmtkfrxl":
        _vj_put(_k, _vj_box(12), [_t])

# the walker (a solid green square), its green frame and the maroon wall block; no pink (pink means "sends you back"
# in this family) and nothing that looks like a button (18-Oct: the old pink and white walker read as one)
_vj_put("vjwalker", [[14, 14], [14, 14]], ["walker"])
_vj_put("vjframew", _vj_box(14), ["frame-w"])
_vj_put("vjwall", [[13, 13, 13], [13, 13, 13], [13, 13, 13]], ["wall"])


